<section class="page-hero"><div class="container"><span class="eyebrow">Digital knowledge center</span><h1>Ideas for digital progress.</h1><p>Perspectives and practical notes from the world of digital work.</p></div></section>
<section class="content-section"><div class="container"><?php if(!$posts): ?><div class="empty-state"><i data-lucide="newspaper"></i><h2>Articles are coming soon</h2><p>Published articles will appear here.</p></div><?php else:?><div class="product-grid"><?php foreach($posts as $post): ?><article class="product-card"><?php $cover = $this->imageUrl($post['cover_image'] ?? ''); if ($cover !== ''): ?><div class="article-cover"><img src="<?= $this->escape($cover) ?>" alt=""></div><?php endif ?><div class="product-body"><?php if ($post['published_at']): ?><time class="article-date" datetime="<?= $this->escape(date('Y-m-d', strtotime($post['published_at']))) ?>"><?= $this->escape(date('F j, Y', strtotime($post['published_at']))) ?></time><?php endif ?><h2><?= $this->escape($post['title']) ?></h2><p><?= $this->escape($post['excerpt'] ?: '') ?></p><a class="text-link" href="<?= $this->escape(appUrl('/blog/' . $post['slug'])) ?>">Read article <i data-lucide="arrow-right"></i></a></div></article><?php endforeach ?></div><?php endif ?></div></section>
